1	/**
2	 * Тесты расхода на поездку: километры × норма (дл/100 км = мл/км), вверх до 100 мл.
3	 */
4	
5	import { strictEqual } from 'node:assert/strict';
6	import { describe, it } from 'node:test';
7	
8	import { fuelMl } from '../src/index.ts';
9	
10	describe('расход на поездку', () => {
11	  it('ровный акт: 100 км легкового = 100 × 76 = 7600 мл', () => {
12	    strictEqual(fuelMl(100, 'car'), 7600);
13	  });
14	
15	  it('округление вверх до 100 мл: 13 км фургона = 13 × 115 = 1495 мл → 1500', () => {
16	    strictEqual(fuelMl(13, 'van'), 1500);
17	  });
18	
19	  it('неизвестный класс — null, как у rateFor', () => {
20	    strictEqual(fuelMl(50, 'motorcycle'), null);
21	  });
22	
23	  it('нулевой пробег — нулевой расход', () => {
24	    strictEqual(fuelMl(0, 'truck'), 0);
25	  });
26	});
27

